UPDATE public.leagues SET temporada_ref='2026/2027' WHERE pais IN ('Inglaterra','França','Espanha','Alemanha','Itália','Portugal');
INSERT INTO public.leagues(nome,pais,nivel,temporada_ref) SELECT '3. Liga','Alemanha',3,'2026/2027' WHERE NOT EXISTS(SELECT 1 FROM public.leagues WHERE pais='Alemanha' AND nivel=3);
