('Inglaterra',3,ARRAY['Plymouth Argyle','Bradford City','Stockport County','Huddersfield Town','Cambridge United','Reading','Sheffield Wednesday','Oxford United','Stevenage','Burton Albion','AFC Wimbledon','Leyton Orient','Luton Town','Mansfield Town','Wycombe Wanderers','Doncaster Rovers','Leicester City','Blackpool','Barnsley','Peterborough United','Bromley','Notts County','Milton Keynes Dons','Wigan Athletic']::text[]),
('Inglaterra',4,ARRAY['Salford City','Barnet','Crewe Alexandra','Gillingham','York City','Walsall','Chesterfield','Cheltenham Town','Bristol Rovers','Rochdale AFC','Grimsby Town','Newport County','Tranmere Rovers','Exeter City','Accrington Stanley','Fleetwood Town','Swindon Town','Shrewsbury Town','Colchester United','Rotherham United','Oldham Athletic','Port Vale','Northampton Town','Crawley Town']::text[]),
('França',1,ARRAY['Monaco','Lille','Rennes','Lyon','Paris FC','Paris Saint-Germain','Brest','Lorient','Nice','Lens','Strasbourg','Angers','Marseille','Le Mans','Toulouse','Auxerre','Troyes','Le Havre']::text[]),
('França',2,ARRAY['Saint-Étienne','Red Star','Montpellier','Reims','Nancy','Annecy','Dijon','Pau','Sochaux','Metz','Dunkerque','Guingamp','Nantes','Grenoble','Rodez','Boulogne-sur-Mer','Clermont Foot','Laval']::text[]),
('Espanha',1,ARRAY['Barcelona','Atlético Madrid','Real Betis','Real Madrid','Sevilla','Real Sociedad','Alavés','Deportivo La Coruña','Celta Vigo','Athletic Bilbao','Villarreal','Espanyol','Rayo Vallecano','Getafe','Racing Santander','Osasuna','Levante','Elche','Valencia','Málaga']::text[]),
('Espanha',2,ARRAY['Almería','Eibar','Castellon','Mallorca','CE Sabadell','Sporting Gijón','Girona','Burgos','Real Oviedo','Granada','Real Valladolid','Tenerife','Real Club Celta B','Eldense','Las Palmas','Leganés','Futbol Club Andorra','Córdoba','Real Sociedad B','Cádiz','Ceuta','Albacete']::text[]),
('Alemanha',1,ARRAY['SC Freiburg','Borussia Dortmund','Bayern de Munique','Bayer Leverkusen','RB Leipzig','FC Augsburg','Werder Bremen','Mainz 05','SV Elversberg','1. FC Köln','VfB Stuttgart','Hamburger SV','Schalke 04','Eintracht Frankfurt','SC Paderborn','Union Berlin','TSG Hoffenheim','Borussia Mönchengladbach']::text[]),
('Alemanha',2,ARRAY['Hertha BSC','1. FC Nürnberg','1. FC Heidenheim','1. FC Magdeburg','VfL Wolfsburg','Kaiserslautern','FC St. Pauli','Energie Cottbus','Arminia Bielefeld','VfL Osnabrück','Eintracht Braunschweig','VfL Bochum','Hannover 96','Darmstadt 98','SpVgg Greuther Fürth','Dynamo Dresden','Karlsruher SC','Holstein Kiel']::text[]),
('Alemanha',3,ARRAY['Duisburg','Viktoria Köln','Rot-Weiss Essen','Hansa Rostock','Saarbrücken','TSG 1899 Hoffenheim II','SV Waldhof Mannheim','Preußen Münster','Alemannia Aachen','Fortuna Düsseldorf','SC Verl','Fortuna Köln','Jahn Regensburg','Stuttgart II','FC Ingolstadt','Wehen Wiesbaden','SG Sonnenhof','Würzburger Kickers','Meppen','TSV Havelse']::text[]),
('Itália',1,ARRAY['Inter de Milão','Lazio','Roma','Cagliari','Milan','Juventus','Como','Napoli','Frosinone','Atalanta','Sassuolo','Torino','Lecce','Bologna','Udinese','Monza','Genoa','Parma','Fiorentina','Venezia']::text[]),
('Itália',2,ARRAY['Palermo','Mantova','Modena','Sudtirol','Ascoli','Avellino','Pisa','Benevento','Hellas Verona','Cesena','Padova','Arezzo','Virtus Entella','Cremonese','Empoli','LR Vicenza','Carrarese','Sampdoria','Catanzaro','Juve Stabia']::text[]),
('Portugal',1,ARRAY['Porto','Benfica','Sporting CP','Santa Clara','Arouca','Académico de Viseu','Alverca','Gil Vicente','Braga','Estrela da Amadora','Moreirense','Marítimo','Famalicão','Rio Ave','Vitória de Guimarães','Nacional','Casa Pia','Estoril Praia']::text[])), incoming AS (
SELECT l.id AS league_id,g.pais,unnest(g.nomes) AS nome FROM groups g JOIN public.leagues l ON l.pais=g.pais AND l.nivel=g.nivel
), updated AS (
UPDATE public.clubs c SET league_id=i.league_id,pais=i.pais,temporada_ref='2026/2027' FROM incoming i WHERE c.nome=i.nome RETURNING c.id
), detached AS (
UPDATE public.clubs c SET league_id=NULL WHERE c.league_id IS NOT NULL AND c.temporada_ref='2025/2026' AND NOT EXISTS(SELECT 1 FROM incoming i WHERE i.nome=c.nome) RETURNING c.id
)
INSERT INTO public.clubs(nome,league_id,pais,temporada_ref)
SELECT i.nome,i.league_id,i.pais,'2026/2027' FROM incoming i WHERE NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.nome=i.nome);
